delete from public.trainer_goals where trainer_id = (select id from public.trainers where slug = 'fitsista-hull' and claimed_by is null);
insert into public.trainer_styles (trainer_id, style_slug) select id, s from public.trainers, unnest(array['boxing', 'strength', 'functional']::text[]) s where slug = 'fitsista-hull' and claimed_by is null and status = 'published' on conflict do nothing;
insert into public.trainer_goals (trainer_id, goal_slug) select id, g from public.trainers, unnest(array['weight-loss', 'confidence', 'general-fitness']::text[]) g where slug = 'fitsista-hull' and claimed_by is null and status = 'published' on conflict do nothing;

commit;

select count(*) as real_trainers from public.trainers where is_sample = false and status = 'published';
